    const size = p.c ? `<p class="small"><span class="tag">${sizeName(sz)}</span> ${money(spent)} spent here by every League; a ${sizeName(sz + 1)} at ${money(sizeAt(sz + 1))}${p.slots ? `, the next slot at ${money(slotAt(p.slots - 1))}` : ''}. Visitors: ${p.c.vw || 0} this week, ${p.c.vy || 0} this year${p.c.vly ? `, ${p.c.vly} last year` : ''}. Crowds here: about ${CROWD_AT(sz).toLocaleString()} for an ordinary battle, at ${money(TICKET_AT(sz))} a ticket.</p>`
      : `<p class="small">The seat counts as your biggest gym city (a ${sizeName(sz)}) for its Stadium's crowds: about ${CROWD_AT(sz).toLocaleString()} for an ordinary battle, at ${money(TICKET_AT(sz))} a ticket, and more for the Elite Four and title battles.</p>`;
    // (0.67.0) the build controls: upgrades of what is here inline, new buildings in one closed list (a row each)
    const locked = p.none ? [] : Object.keys(UPGRADES).map(k => ({ k, ck: buildCheck(where, k) })).filter(x => x.ck.why && /needs a |^Opens at /.test(x.ck.why));
    const opts = p.none ? [] : Object.keys(UPGRADES).map(k => ({ k, ck: buildCheck(where, k) })).filter(x => !x.ck.why);
    const bBtn = (k, ck, label) => `<button class="btn small" data-act="build" data-w="${where}" data-k="${k}"${canSpend(ck.cost) ? '' : ' disabled'} title="${esc(UPGRADES[k].text)}${ck.restore ? ` Restoring a level you lost here in the red costs ${Math.round(RESTORE_SHARE * 100)}% of its price.` : ''}">${label} (${money(ck.cost)})</button>`;
    const has = k => k === 'stadium' ? !p.none : b.some(x => x.k === k && x.lv);
