    const newList = news.length ? `<details class="hist buildlist"><summary><b>Build something new</b> <span class="small muted">${news.length} option${news.length === 1 ? '' : 's'}, from ${money(Math.min(...news.map(x => x.ck.cost)))}</span></summary>
      <ul class="mini buildopts">${news.map(({ k, ck }) => `<li><span><b>${UPGRADES[k].name}</b>${UPGRADES[k].slotless ? ' <span class="small muted">(no slot)</span>' : ''} <span class="small muted blurb">${esc(BUILD_BLURB[k] || '')}</span></span>${bBtn(k, ck, ck.restore ? 'Restore' : 'Build')}</li>`).join('')}</ul>
      ${locked.length ? `<p class="small muted">Not yet: ${locked.map(x => `${UPGRADES[x.k].name} (${esc(x.ck.why)})`).join('; ')}</p>` : ''}</details>`
      : locked.length ? `<p class="small muted">Not yet: ${locked.map(x => `${UPGRADES[x.k].name} (${esc(x.ck.why)})`).join('; ')}</p>` : '';
