// (0.67.0) a line on what each building is for, on the Cities page's build list (the full text is its tooltip)
const BUILD_BLURB = { stadium: 'Seats for ticket income; opens its add-ons', stand: 'A home edge from the crowd', crew: 'The gym\'s type hits harder', video: 'Better picks against the challenger', warmup: 'Lead Pokémon start a stage up', hotel: 'Rooms for challengers in town', center: 'Draws challengers, shorter rests', berry: 'Sells berries or feeds the ranch', hall: 'Elite Four and Champion grow faster',
  school: 'Raises gym trainers of this gym\'s type', tutor: 'Teams learn coverage moves sooner', lab: 'Better trips and finds, League-wide', store: 'Held items for your staff', airport: 'A lane and visitors from another region', wx: 'Each gym\'s weather or terrain',
  corner: 'Takings that swing, and rare prize Pokémon', contest: 'Bug finds and a gate every 8 weeks', pier: 'Steady Water finds', fossil: 'Revives fossils', scout: 'Better finds and more hiring storage', sanct: 'Income and prestige while its legendary is yours',
  ranch: 'More ranch room', lane: 'Migration from another region', safari: 'Quarterly finds from kept lines', daycare: 'Breeds from your pool', academy: 'A loyal prospect a year' };
// (0.67.0) the region's towns where you have no gym, in one panel, each with the move-a-gym control
function townsPanel(ps, gm, gymOpts) {
  if (!ps.length) return '';
  return `<section class="panel"><div class="ph"><h2>Towns without your gym</h2><span class="muted">${ps.length}</span></div>
    <ul class="mini towns">${ps.map(p => { const lgs = gm[p.c.id] || [], cs = cityState(p.c, lgs); return `<li><span><b>${esc(p.name)}</b> <span class="tag">${sizeName(citySize(p.c))}</span>${siteOn(p.c) ? ' <span class="tag gold">Legendary site</span>' : ''}</span><span class="small muted">${lgs.length ? `${lgs.map(lgShort).join(', ')} gym${lgs.length > 1 ? 's' : ''}${cs.tier ? `, ${TIER_NAMES[cs.tier].toLowerCase()} for the ${leagueName(cs.ctrl)}` : ''}` : 'No gyms'}</span></li>`; }).join('')}</ul>
    <div class="confirm-row movegym"><label class="small">Move <select id="movegymsel" aria-label="Gym to move">${gymOpts}</select></label><label class="small">to <select id="movetownsel" aria-label="Town to move it to">${ps.map(p => `<option value="${p.c.id}">${esc(p.name)}</option>`).join('')}</select></label><button class="btn small" data-act="movegym"${canSpend(MOVE_FEE) ? '' : ' disabled'}>Move (${money(MOVE_FEE)})</button></div>
    <p class="small muted">Everything you built in the gym's old city is lost.</p></section>`;
}
// (0.65.0) the keep grade for the catching buildings; (0.66.0) each the League's grade floor unless set here
function keepPanel() {
  const ks = [['contest', 'Bug Catching Contests'], ['pier', 'Fishing Piers'], ['fossil', 'Fossil Labs']].filter(([k]) => myPlaces().some(p => !p.none && p.b.some(x => x.k === k))); if (!ks.length) return '';
  const r = ranchRules(), fl = (r && r.floor) || 1, own = (S.fin.keepB || {});
  const sel = (k, n) => `<label class="small">${n} <select class="keepgsel" data-k="${k}" aria-label="Keep grade: ${n}"><option value="0"${own[k] ? '' : ' selected'}>League floor (${fl > 1 ? gradeStars(fl) + ' and up' : 'keep everything'})</option>${[1, 2, 3, 4, 5].map(g => `<option value="${g}"${own[k] === g ? ' selected' : ''}>Keep ${gradeStars(g)} and up</option>`).join('')}</select></label>`;
  return `<section class="panel"><div class="ph"><h2>Keep grade</h2><span class="muted">${ks.map(x => x[1]).join(', ')}</span></div>
    <p class="small">Finds below the keep grade are sold back at once for a third of their value. Each building uses your League's grade floor (set under Ranch rules on the <button class="tlink" data-act="nav" data-v="ranch">Ranch</button> page) unless you give it its own here. A find for a full ranch makes room if your rules say so, else it is sold back. Both show in the ranch log.</p>
    <div class="confirm-row">${ks.map(([k, n]) => sel(k, n)).join(' ')}</div></section>`;
}
// (0.66.0) the ranch rules (the Pool tab of the Ranch page)
function rulesPanel() {
  const r = ranchRules(); if (!r || r.ai) return '';
  const y = S.fin.rrY && S.fin.rrY.season === S.season ? S.fin.rrY : { n: 0, money: 0 }, two = nLeagues() > 1;
  const chk = (f, label, title) => `<label class="small" title="${esc(title)}"><input type="checkbox" class="rrf" data-f="${f}"${r[f] ? ' checked' : ''}> ${label}</label>`;
  const num = (f, lo, hi, label) => `<label class="small">${label} <input type="number" class="rrf" data-f="${f}" min="${lo}" max="${hi}" value="${r[f]}" style="width:4.5em"${r.idle ? '' : ' disabled'}></label>`;
  return `<section class="panel"><div class="ph"><h2>Ranch rules</h2><span class="muted">This year: ${y.n} sold by the rules for ${money(y.money)}</span></div>
    <p class="small">What the ranch does on its own. A <b>spare</b> is any ranch Pokémon nobody fields, reserves, locks or names in a team plan${r.cond ? '' : ', and not an alpha, Delta, shiny or Radiant'}; the rules only ever sell spares. Weakest means lowest value (line strength, grade, rarity, condition and your League's meta), so a rare line or a meta favourite survives a low grade.</p>
    <div class="confirm-row" id="rrrules">
      <label class="small" title="Trips, hunts, charters, outbreak trips, Safari finds, the Day Care's young and the catching buildings">Grade floor <select class="rrf" data-f="floor" aria-label="Grade floor"><option value="0"${r.floor > 1 ? '' : ' selected'}>Off</option>${[2, 3, 4, 5].map(g => `<option value="${g}"${r.floor === g ? ' selected' : ''}>Keep ${gradeStars(g)} and up</option>`).join('')}</select></label>
      ${chk('room', 'Make room for better finds', 'A find for a full ranch replaces your weakest spare if it is worth more (the spare is sold back)')}
      ${chk('idle', 'Idle clear-out', 'Sell spares nobody has fielded for a while, keeping your best of each line')}
      ${num('idleN', RR_IDLE_N[0], RR_IDLE_N[1], 'after weeks')}${num('idleK', RR_IDLE_K[0], RR_IDLE_K[1], 'keep of each line')}
      ${chk('list', 'List first', `Idle clear-outs, and your weakest spares once the ranch is within ${RR_NEAR} of full, are listed for other Leagues (you get ${Math.round(SALE_SHARE * 100)}%) for ${RR_LIST_WEEKS} weeks, up to ${RR_LIST_MAX} at once, then sold back`)}
      ${chk('cond', 'Conditioned too', 'Let the rules sell alphas, Deltas, shinies and Radiants like any other spare')}
    </div>
    <p class="small muted">Finds below the floor sell back at once for a third of their value. Make room sells the spare back at once. ${two ? '' : 'List first needs another League to sell to. '}Every sale the rules make is in the ranch log with its reason.</p></section>`;
}
// (0.64.0) the item bag and the Department Stores' shelves
const SHELF_NAMES = ['Poké Mart', '2F', '3F', '4F'];
function bagPanel() {
  if (!bagRule()) return '';
  const bag = bagOf(), used = bagUsed(), fl = storeFloors(), own = Object.keys(bag).filter(k => bag[k] > 0 && ITEMS[k]);
  const holders = {}; for (const id of seniorIds()) for (const m of T(id).team) if (m.item && m.bagLg === ME()) (holders[m.item] = holders[m.item] || []).push(`${T(id).name}'s ${m.sp}`);
  const shelf = fl ? [1, 2, 3, 4].filter(n => n <= fl).map(n => `<li><b>${SHELF_NAMES[n - 1]}</b> ${Object.keys(ITEMS).filter(k => shelfOf(k) === n && k !== 'everstone').map(k => `<button class="btn small ghost" data-act="buyitem" data-k="${k}" title="${esc(ITEMS[k].desc)}"${canSpend(itemPrice(k)) ? '' : ' disabled'}>${esc(itemName(k))} ${money(itemPrice(k))}</button>`).join(' ')}</li>`).join('') : '';
  return `<section class="panel"><div class="ph"><h2>Item bag</h2><span class="muted">${own.reduce((a, k) => a + bag[k], 0)} items</span></div>
    <p class="small">Your staff hold tier 1 items from the League's free supply as before (Gym Leaders from the fourth gym, the Elite Four and Champion on every Pokémon). Tier 2 and 3 items come only from this bag: your Gym Leaders, Elite Four and Champion take the best of it, one item a Pokémon, and it comes back when a Pokémon leaves the team. Challengers you hire to those posts bring theirs in. Buy at a Department Store: your best Store's floors set what is on sale, and each floor above a shelf takes ${Math.round(STORE_FLOOR_OFF * 100)}% off it.</p>
    ${own.length ? `<ul class="mini">${own.map(k => `<li><span><b>${esc(itemName(k))}</b> ×${bag[k]} <span class="small muted">${used[k] || 0} held${holders[k] ? ': ' + holders[k].map(esc).join(', ') : ''}</span></span></li>`).join('')}</ul>` : '<p class="small muted">The bag is empty.</p>'}
    ${fl ? `<ul>${shelf}</ul>` : '<p class="small muted">Build a Department Store in a gym city to buy items.</p>'}</section>`;
}
// ---------- glossary ----------
// built from the game's own data (abilities, moves, items, traits), plus hand-written terms
let glossSec = 'all', glossQ = '';
const RATING_TEXT = { str: 'Smarter move choices and send-outs in battle, and calling dodges.', trn: 'How many levels training weeks give.', bnd: 'Friendship, critical hits and hanging on at 1 HP.', sct: 'Finds better wild Pokémon when exploring.', nrv: 'Holds up under pressure, most of all in big battles.' };
const GLOSS_TERMS = {
  plans: [
    ['Challenge', 'Battle the next Gym Leader for a badge.'],
    ['Train', 'Every Pokémon gains levels; ones far behind the strongest catch up faster.'],
    ['Explore', 'Meet wild Pokémon and try to catch one. Sometimes turns up a held item.'],
    ['Seek', 'Battle a legendary that has appeared, at full strength every time. The damage adds up across weeks, and when it is worn down or its five weeks are up it goes to the trainer who did the most (ties are fought out). Luck swings each attempt hard, and a failed attempt still earns experience.'],
    ['Who decides', 'Every trainer chooses their own week.'],
    ['Newcomers', `There is no draft. About ${NEWCOMERS_PER_LEAGUE} new trainers set out for each League every year, one at a time. A circuit has no fixed number of places: everyone who wants to challenge does. A challenger who keeps going out early (${GIVE_UP_RUNS} or more runs in a row that end sooner than a typical run) gives up after their first ${GIVE_UP_GRACE} years, which keeps the field in check.`],
    ['Calendar', `One continuous world. A year is ${YEAR_WEEKS} weeks, twelve months of four, and it never stops for a tournament or an offseason. Every trainer has a birthday week, when they grow a year older and their ratings move; staff retire then, and a challenger who decides to retire sees their run through first. Only the wall report, the awards, the meta report and the ban vote wait for New Year.`],
    ['Run', `A challenger's trip around the circuit. They set out for the first gym with their best ${START_TEAM} Pokémon and catch more on the way. The run ends on a third loss at one gym, or after the Elite Four and Champion. Then they rest ${REST_WEEKS[0]} to ${REST_WEEKS[1]} weeks and set out again from the first gym; one who reached the Elite Four and moves on to a different League rests only ${REST_QUICK[0]} to ${REST_QUICK[1]}.`],
    ['Free agent', 'A trainer between circuits. They join one within a few weeks.'],
    ['God mode', 'An option chosen at setup. Its page opens a League and edits any trainer directly: name, age, ratings and potential.'],
    ['Walking partner', "A trainer's highest-level Pokémon walks beside them out of its ball, and its friendship grows faster."],
  ],
  battle: [
    ['Same-type attack', "A move that matches one of the user's types hits 50% harder."],
    ['Super effective', 'Hits a type weak to it for double damage (×4 against two weaknesses); "not very effective" is half.'],
    ['Critical hit', 'A hit that does 50% more. Bond and some moves and abilities make them likelier.'],
    ['Solid hit', 'Now and then (6%) a move lands cleanly and does 30% more.'],
    ['Glancing blow', 'Sometimes (8%) a move only grazes and does 40% less.'],
    ['Momentum', "A Pokémon that lands two hits in a row hits 5% harder, three or more 10% harder, until it's interrupted."],
    ['Miss', 'Moves rarely miss: their accuracy is pulled halfway toward 100% (an 80% move hits 90%).'],
    ['Dodge', "A faster Pokémon can dodge an attack (up to 12%), more often with a sharp trainer's Strategy."],
    ['Priority', 'Moves like Quick Attack go before anything else that turn; otherwise the faster Pokémon moves first.'],
    ['Stat stages', 'Boosts and drops from −6 to +6; each stage up is +50% (so +2 is double), each stage down shrinks the stat.'],
    ['Utility move', 'A move that does no damage in the games. Here it does light damage and keeps its effect. Boosting or healing works once per battle.'],
    ['Flinch', 'A Pokémon hit first by a flinching move may lose its turn.'],
    ['Burn', 'Loses a little HP each turn, and its physical attacks do half damage.'],
    ['Paralysis', "Speed is halved, and a quarter of the time it can't move."],
    ['Poison', 'Loses 1/8 of its HP each turn. Bad poison starts smaller and gets worse every turn.'],
    ['Sleep', "Can't move for 1–3 turns."],
    ['Harsh sunlight', 'Fire moves ×1.25, Water moves ×0.75. Powers Chlorophyll and Solar Power.'],
    ['Rain', 'Water moves ×1.25, Fire moves ×0.75. Powers Swift Swim and Rain Dish.'],
    ['Sandstorm', "Chips HP each turn from anything that isn't Rock, Ground or Steel; Rock types gain Sp. Def."],
    ['Snow', 'Ice types gain Defense. Powers Slush Rush and Ice Body.'],
    ['Gym weather', "Each gym has weather that suits its type (a Fire gym is sunny)."],
    ['Hazards', 'Stealth Rock and Spikes hurt every Pokémon the other side sends in afterwards.'],
    ['Mega Evolution', 'League battles only. A Pokémon holding a Mega Stone Mega Evolves when it comes out: new types and much higher stats.'],
    ['Battle Bond', 'A long-time partner at max friendship can bond with its trainer and transform after its first knockout in League battles. If it falls, the team falters.'],
    ['Stalemate', 'If nobody loses HP for 12 turns in a row, the battle is decided on remaining HP.'],
  ],
  mons: [
    ['IVs', "A Pokémon's hidden potential in each stat, graded from Poor to Perfect."],
    ['Nature', 'Raises one stat by 10% and lowers another, and gives a temperament: a small effect off the field (see Temperaments).'],
    ['Temperament', 'What a nature does off the field: nerves on the big stage, faster learning and more. Each one is listed under Temperaments.'],
    ['Friendship', 'Grows with time on a team. High friendship helps in battle and is needed for Battle Bond.'],
    ['Form', 'Recent results make a Pokémon run hot (On fire, Hot) or cold (Cold, Slumping), which nudges its strength.'],
    ['Hidden ability', 'The rarer third ability slot. 25% of Pokémon have it, 50% of shinies, alphas and Deltas.'],
    ['Alpha', 'A bigger, stronger wild Pokémon: outstanding IVs and already on a hot streak.'],
    ['Shiny (✦)', 'A rare wild Pokémon with perfect IVs that arrives on fire.'],
    ['Radiant (✧)', "Rarer than a shiny. It wears its species' shiny colors, always has at least Good IVs, and has an ability its species never gets that's stronger in battle than any it does. The ability stays through evolution."],
    ['Delta (Δ)', 'A rare Pokémon with an unusual second type and outstanding IVs.'],
    ['Legendary / Mythical', `One-of-a-kind Pokémon: there is one of each in the whole world, held by one trainer or waiting for a new partner (one for each region of the world that has it at home, when a custom region shares it). The great legendaries appear through story events; others roam, come with storms, are found while exploring or choose a trainer. Each region's own legendaries turn up about ${LEGEND_HOME_MUL} times as often in a League of their region and half as often elsewhere. A legendary (an Ultra Beast or a Paradox Pokémon too) only battles for a challenger with enough badges for its strength: base stats under 600 from ${OBEY_BADGES[0][1]} badges, under 680 from ${OBEY_BADGES[1][1]}, the strongest from ${OBEY_BADGES[2][1]}. At the Elite Four every Pokémon obeys. Your staff are never held back.`],
    ['Legendary site', `A gym city where a legendary appeared or was caught (it remembers the last four). Every League with a gym there can build a Sanctuary. A Sanctuary is open while one of the site's legendaries is with the League: held by its staff, by a challenger on its circuit, or stored in the Sanctuary's vault. Open, it earns ${UPGRADES.sanct.income.map(money).join(', ')} a week by level and adds ${SANCT_PRESTIGE} prestige a level each New Year; sealed, it earns and costs nothing until one comes back. Ask a holder to store their legendary on the Ranch page: staff agree or refuse by their ambition and record, and a challenger asks ${money(VAULT_FEE[0])} to ${money(VAULT_FEE[1])} by its strength (or hire them and ask again). A stored legendary's years with a partner stop counting, and one of your Elite Four or your Champion without a legendary can field it; it belongs to the League and comes back to the vault when they leave the post. Staff let go after storing their own take it hard: a sure grudge. Rival Leagues build them too.`],
    ['Roaming legendary', "Raikou, Entei, Suicune, Latias or Latios moving between towns for 7–9 weeks. Challengers exploring on the way to its town (or the next one) may find it among their wild Pokémon and catch it like any other."],
    ['Legendary storm', "Four weeks of weather over the whole region, brought by Articuno (blizzard), Moltres (heat wave), Zapdos (electric storm), Thundurus (thunderstorm), Tornadus (gale) or Landorus (who calms the skies after Tornadus or Thundurus). It powers up one type for everyone, and when it passes the legendary chooses the challenger who won the most battles in it, whatever their type."],
    ['Legendary partner', "A legendary or mythical Pokémon stays with a trainer for 5–8 years, then moves on at New Year (the years stop counting while it is stored in a Sanctuary). It waits for a new partner, keeping its lifetime record, and the next trainer to find or be given it gets that same Pokémon at their own level. It never goes back to a trainer it has already been with. Baby legendaries count from their catch. Ultra Beasts and Paradox Pokémon aren't included."],
    ['Baby legendary / Rare find', 'Pokémon like Cosmog or Meltan that grow into legendaries. Only one exists in the world at a time.'],
    ['Paradox', `Ancient and Future Pokémon. When an expedition to Area Zero finds Koraidon, Miraidon or Terapagos, the crater stays open in that League for a year and exploring challengers can find a Paradox Pokémon. One of each in the world at a time; they aren't legendaries, so a trainer can hold one beside a legendary, and they don't move on.`],
    ['Banlist', `Each New Year a League's trainers (challengers, Gym Leaders, the Elite Four and the Champion) vote on banning five Pokémon drawn at random from the year's top 20 performers, with at most two legendaries on the ballot. They vote against Pokémon that beat them, that their team is weak to or that their rival uses, never ones on their own team. Each votes Allow or a ban of 1 to ${BAN_MAX_SEASONS} seasons, and a ban passes for the longest length that more than half of them back. A ban covers the Pokémon, what it evolves from and what it evolves into. Challengers let banned Pokémon go; Gym Leaders, the Elite Four and the Champion get a replacement.`],
    ['Ultra Beast', 'Comes through an Ultra Wormhole. One chance to catch it.'],
    ['Wildcard', "A specialist's one strong Pokémon outside their type, kept for coverage."],
  ],
  league: [
    ['Badge circuit', 'The eight gyms challengers work through on a run, each on their own clock and in any order they choose. With eight badges a challenger takes on the Elite Four and the Champion as soon as they are ready, after up to three weeks spent filling their team.'],
    ['Set level', `Every battle on the circuit is fought at a set level for both sides: gyms by the badges a challenger already holds (${GYM_LV.map((l, k) => `${k}: Lv ${l} with ${GYM_SIZE[k]}`).join(', ')}), the Elite Four ${E4_LV.join(', ')}, the Champion ${CHAMP_LV}. Challengers' Pokémon have no levels of their own: each one takes the form and moves it would have at the level of its trainer's next battle, so nobody can out-level a gym.`],
    ['Who fights', "A challenger fields as many Pokémon as the trainer in front of them, picked for the matchup. A trainer with a higher Strategy rating picks better."],
    ['Gym trainers', `Each gym has ${GYM_TRAINERS} gym trainers, each with one Pokémon fewer than the leader. A typed leader's gym trainers share at least one type with them and field their own class's types; an untyped leader's can be of any class. A challenger must beat them, then the leader, and is healed between battles. A gym trainer already beaten stays beaten.`],
    ['Founding', 'When you found your League you place its Champion, Elite Four and eight Gym Leaders by hand, from candidates the game finds and the founding field. Everyone you don\'t place sets out as a challenger, and gym trainers are taken from the circuit.'],
    ['Stepping down', `A member of staff only steps down after a long career: past their career length and at least ${STEP_DOWN_YEARS} years in posts. They announce it a year ahead and leave on their next birthday.`],
    ['Career length', 'Set by the age a trainer started at: those who start young have the longest careers (about 22 to 30 years from age 10 to 14), late starters the shortest (about 8 to 16 from 35). Strong ratings and a title add up to three years, and long service in posts up to two more.'],
    ['Ambitions', `Each member of staff has one: promotion (a gym trainer wants a gym, a Gym Leader a later gym or the Elite Four, an Elite Four member a higher seat; seat #4 wants the Champion's seat and waits), stay put, or another run as a challenger. It is set when they take a post and can change on a birthday. Promotion waits ${AMB_WAIT_YEARS} years in the post and shows as Restless in the last; then a Gym Leader or Elite Four member gives ${QUIT_NOTICE} weeks' notice and leaves with a grudge unless promoted (a gym trainer just goes). The Champion always stays put.`],
    ['Another run', `A Gym Leader with ${COMEBACK_STREAK} outstanding years in a row (now and then anyone younger without a title) may ask to go back to the circuit as a challenger. Let them go (they come back sharper and can be hired again), or they leave anyway a year after asking.`],
    ['Money', 'Every League keeps books (rival Leagues spend by their aim). In: an entry fee for every run begun on your circuit, a wall prize at New Year that shrinks with every trainer let through, Stadium tickets, Hotels, Berry Farms and your share of each gym city\'s income. Out: salaries every week (the post and the trainer\'s OVR, reviewed each New Year), signing fees for anyone joining from outside, severance for anyone let go (nothing once they have announced stepping down or given notice), raises, bans and buildings. In the red, salaries are still paid but nothing new can be bought. The Money page has the books.'],
    ['Being in the red', `Every ${RED_BITE_WEEKS} weeks in the red the League\'s best-paid member of staff (never the Champion) gives twelve weeks\' notice, and leaves unless the League is back above zero first. In the red nothing new can be bought, and automatic hires take the cheapest trainer who fits, with no signing fee. Upkeep goes unpaid and every building lapses: Hotels and Berry Farms earn nothing, Stadiums sell only their first 500 seats and their add-ons do nothing, and halls, Centers, the scouting office and the academy do nothing. Every ${DECAY_WEEKS} weeks unpaid in a row the costliest building loses a level (in a shared city a rival may buy it at ${Math.round(DISTRESS_SHARE * 100)}% of its cost). In the red at ${FOLD_YEARS} New Years running, with debts its buildings sold at half can't cover, a League folds.`],
    ['Folding', `A League in the red at ${FOLD_YEARS} New Years running, whose buildings sold at half could not clear its debts, closes for good. Rivals with a gym in its shared cities buy what they can at a distress price; the rest is lost. Its staff and challengers scatter to other circuits (older or struggling ones retire), its contracts end, and its place in the world is free. Old records still name it. If your League folds, you found a fresh one by hand in the same region, with the usual starting fund.`],
    ['Selling buildings', `Any building level can be sold from the Cities page for ${Math.round(SELL_SHARE * 100)}% of what it cost; your standing in that city drops by what the level had added. Rival Leagues in the red sell one level a month, the costliest first. The levels the seat\'s Stadium came with can\'t be sold.`],
    ['Aims', 'Each rival League has an aim. A wall-builder hires the best, counters the meta, builds Stadiums and their add-ons and pays for bans; a star-maker hires young and builds Pokémon Centers, training halls, a youth academy and a scouting office; a money-maker keeps wages down, builds Hotels where visitors are, Berry Farms and Stadiums, and holds a reserve. A rival in the red turns money-maker until it is back on its feet, then goes back to its old aim; a money-maker by choice far richer than the world\'s average turns to a wall or to stars. A rich rival bids over the asking pay when it hires, and at New Year may pay to replace its weakest Elite Four member or Gym Leader with a clearly better trainer. It never builds more than its running income can keep up.'],
    ['Standing and control', `Standing is a League's reputation in a city where it has a gym. Each New Year it grows from how the gym held against the region's average (a point per percentage point), from presence (a point a year for every ${money(PRESENCE_PER)} of buildings standing there; nothing while they have lapsed), from prestige (a tenth of the League's prestige in every home city) and from local heroes (staff whose hometown it is: ${HERO_PTS.champion} for the Champion, ${HERO_PTS.e4} an Elite Four member, ${HERO_PTS.leader} a Gym Leader, ${HERO_PTS.gymtrainer} a gym trainer). A League under half the leader's standing gains half again as fast. Then all standing fades by a quarter. Control is graded by the leader's lead over the second League (or the strongest renown): Contested (under ${Math.round((TIER_AT[0] - 1) * 100)}% ahead: income shared by standing), Leaning (the leader takes ${Math.round(TIER_SHARE[1] * 100)}%), Held (${Math.round(TIER_SHARE[2] * 100)}% and prestige) and Stronghold (more than ${TIER_AT[2]} times the second: ${Math.round(TIER_SHARE[3] * 100)}%, more prestige, a small crowd edge for its gym there, hometown trainers who sign for less prestige, and first refusal on a rival's distress sale there). A city earns ${[0, 1, 2, 3].map(k => money(CITY_INCOME_AT(k))).join(', ')} a week as a Town, City, Metropolis and Megalopolis, plus what its visitors spend; a League alone there takes it all, less any renown's slice.`],
    ['Renown', `What a League earns in a city where it has no gym, usually in another region: a quarter of its prestige spillover, ${RN_BADGE} for each badge its contenders win there, ${RN_TITLE} in every gym city of a League its contender beats for the title, and ${RN_WORLD} in every other region's cities for a World title. It fades by a quarter each New Year. Renown never controls a city, but it counts at a third of its size (never more than half the leader's standing) against the leader's lead, which can drop them a tier, and takes up to ${Math.round(RN_SLICE * 100)}% of the city's income, shared by renown. Each city's renown shows on the Cities page.`],
    ['The regional field', `Challengers belong to a region, not a League. Before each run a challenger draws which of the region's Leagues to take on: a League's prestige counts (more for strong challengers), so does its standing in the challenger's hometown, and a League that Held or better their hometown keeps their loyalty for ${LOYAL_YEARS} years. Weaker challengers also favour Leagues where runs get further and quieter Leagues with fewer challengers. A new challenger may be drawn to a League from another region with renown in their hometown. A region's field aims at about ${FIELD_PER} challengers a League in it, a little more as its cities grow; newcomers stop coming while it is well past that, and weak challengers give up sooner in a crowded field. You hire from the region's field: your circuit and the region's other challengers resting between runs. The Circuit page shows your League's challengers or the whole field.`],
    ['Hometowns', `Every trainer comes from a city or town of the region they were made in (on their profile). Staff in their hometown lift their League's standing there; when another League hires them away, that goes with them. A trainer from a city that is a League's Stronghold needs ${Math.round((1 - STRONG_RECRUIT) * 100)}% less prestige to sign for it.`],
    ['League table', 'Every League ranked by money, with last year\'s income and spending, the wage bill, cities controlled, the wall and its share of its region\'s challengers. Balance in this game is economic: Leagues should stay close to level, and one that falls behind can catch up (weaker challengers favour walls they can get further against and quieter Leagues, a League far behind in a city gains standing faster, and stars ask a little more of a League far richer than the rest). A rival drawing well under an even share of its region\'s field rebuilds: it spends only in its strongest city, sends a contender and trims its costliest staff until its share recovers.'],
    ['Post names and themes', `Each League names its own posts. A <b>theme</b> is a set of the four names: Classic (Gym Leader, Gym trainer, Elite Four, Champion), Dojo (Sensei, Student, Grandmasters, Master), Court (Warden, Squire, High Council, Sovereign), Board (Branch Head, Associate, Board, Chair), Academy (Professor, Assistant, Faculty, Dean) and Island trials (Kahuna, Trial Captain, Island Elders, Champion); Region default takes the region's own names (Alola's, a custom region's), else the usual ones. A theme also changes a few lines of the news. Pick your League's theme at setup, and type over any name; change them later from the League table (Posts). Rival Leagues draw a theme by their aim (a wall-builder leans to Dojo and Court, a star-maker to Academy and Classic, a money-maker to Board) and their region (Kalos and Galar to Court, Paldea to Academy, Unova to Board, Alola to Island trials; a custom region chooses), and may rebrand when they start rebuilding or change aim for good. Staff carry the titles of the League they serve now; each year's report and the Hall of Fame keep the titles of their day. The posts work the same whatever they're called.`],
    ['League names', `A League takes its name from its seat: the first seat of a region is named for the region (the Kanto League) and each of the other three for its seat (the Victory Road League, the Cerulean Cave League, the Trainer Tower League; a custom region can set its own names). You can name your League and the starting rivals at setup (rivals under Advanced options, Where rival Leagues start) and rename your League from the League table at any time; with Rename rival Leagues on at setup, any League. Names are unique: a League opening at a seat whose old League folded becomes the New … League. A League's past names show on the League table, and each year's report keeps the name it had then.`],
    ['Founders', `A new League is founded by a distinguished recent retiree as a final act, and is named in the League table and its history (the League's own name comes from its seat: see League names). With new Leagues switched on, one may open each New Year once ${growthPace()} years have passed since the last (4, 8 or 12, chosen at setup), if the most prestigious recent retiree has enough prestige for a region with room (at most ${REGION_CAP} Leagues to a region): ${FOUNDER_BARS[0]} for a region's first or second League, ${FOUNDER_BARS[2]} for its third and ${FOUNDER_BARS[3]} for its fourth. Among those regions the founder's is drawn, likelier where there are fewer Leagues (${GROWTH_W.join(', ')} for a region with none, one, two or three) and ${GROWTH_HOME} times as likely in the founder's own region (where they retired); your region has no edge. ${newRegionsOn() ? 'A region with no League yet can take one, which brings its own field of challengers' : 'In this world new Leagues open only in regions that already have one'} (Advanced option Leagues can open in new regions). No founder, no League. Rarely a champion still fit enough becomes its Champion, protected from stepping down and from seat challenges for ten years.`],
    ['Growth', `Every trainer, staff and challengers alike, grows on one curve, a step on each birthday. They improve until their peak (age ${GROW_PEAK}), fastest while young (about ${GROW_STEP[0][1]} points a rating a year up to ${GROW_STEP[0][0]}, ${GROW_STEP[1][1]} to ${GROW_STEP[1][0]}, ${GROW_STEP[2][1]} after), hold, and decline slowly from ${GROW_DECLINE}, faster with age. Growth counts from the start of a career: a late starter improves for ${GROW_LATE} years from the start and declines ${GROW_LATE_DECLINE} years after it, by ${GROW_DECLINE_MAX} at the latest. Talent varies (×${GROW_TALENT[0]} to ×${GROW_TALENT[1]}), as does the coach: a gym trainer is coached by their Gym Leader, Gym Leaders and the Elite Four by the Champion, everyone else by themselves, and a coach's Training speeds growth (Training 50 is the usual pace). A training hall at a member of staff's post adds ${Math.round(GROW_HALL * 100)}% a level and slows their decline. Late Bloomers peak and decline ${GROW_BLOOM} years later. Potential (POT) is where a trainer's growth is heading at their own pace.`],
    ['Prestige', `One scale for trainers and Leagues. A trainer's comes from their career: titles, the Hall of Fame, badges, years and World titles. A League's is earned each New Year (${PRESTIGE_PERFECT} for a perfect year, up to ${PRESTIGE_LET_MAX} for letting through fewer than the world's average, ${PRESTIGE_WORLD} for winning the World Championship, ${TIER_PREST[2]} for each city it Holds and ${TIER_PREST[3]} for each Stronghold (up to half again for a large city), and up to ${PRESTIGE_RANK[0]} for its rank by wealth) and fades by a tenth a year. A retiree founding a League needs ${FOUNDER_BARS[0]} for a region's first or second League, ${FOUNDER_BARS[2]} for its third and ${FOUNDER_BARS[3]} for its fourth; you need ${PRESTIGE_BAR} to leave yours. A prestigious League draws trainers: up to ${Math.round(PRESTIGE_PULL * 100)}% likelier to take its offers and sponsorships, and challengers moving League lean toward it. The League table shows every League's. Since 0.23.0 every trainer also has a prestige minimum for joining a League: nothing up to OVR ${PM_FREE}, then ${PM_PER} for each point above it, plus ${Math.round(PM_REC * 100)}% of their own prestige (at most ${PM_REC_MAX}) and ${PM_FAMOUS} for a famous trainer. A trainer hungry for a post (another League's staff who want promotion, a claimant, and about one challenger in four) needs only ${Math.round(PM_HUNGRY * 100)}% of it, and one holding a grudge against another League ${Math.round(PM_GRUDGE * 100)}%. Below it they won't sign, at founding, for a post or for an offer; candidates show it as Prestige X. Outsiders the game finds for a post are no stronger than the League's prestige can attract. Your own staff moving between posts, and staff who follow you to a new League, are never held back.`],
    ['Contenders', `A League can send challengers at another League as its contenders: its own academy prospects, or a challenger from its circuit it signs. A contender runs only at that League for ${SPON_YEARS} years (renewable), and nobody else can hire them or seat them after a deep run meanwhile. The sponsor pays a weekly stipend; the target still gets their entry fees and pays the sponsor a bounty of ${money(SPON_BOUNTY)} for each title they win there (${money(SPON_E4_BOUNTY)} for a run that reaches the Elite Four). Rival Leagues send them too, by their aim, and may send them at you. Your Contenders page has yours; the year report lists each year's.`],
    ['Founding your own League', `Once your League's prestige reaches ${PRESTIGE_BAR}, you can leave it to found a new League for ${money(LEAVE_FEE)} from its money (on the Money page), if the world has room. The League you leave carries on as a rival with an aim of its own, keeping its money, buildings, staff and history. Up to ${LEAVE_TAKE} members of staff who want promotion come with you, and your academy prospects follow. You place the new League's staff by hand and start with ${money(START_FUND)}. You only ever run one League.`],
    ['Raises and bids', 'A raise keeps a restless member of staff, or one who gave notice over promotion, another year: once per post, for twelve weeks\' pay now and a fifth more after. A bid over the asking pay makes a challenger likelier to take your offer; they keep the higher pay.'],
    ['Cities', 'Your gym cities, the region\'s other cities and towns (six with no gym at first), and your League\'s seat. Build where you have a gym, and at the seat. Every gym has a Stadium (tickets for every battle there; its levels open add-ons for your staff: a Home stand, a Field crew, a Video room and a Warm-up room), and the seat starts with one at level 2; Hotels fill rooms with the challengers in town; Pokémon Centers draw challengers and shorten their rests; Berry Farms sell berries or feed the ranch; Trainer\'s Schools raise gym trainers and help a gym\'s staff grow; Move Tutors widen coverage; a Research Lab improves catching trips; Department Stores sell held items for the item bag; and at the seat a training hall, a scouting office, a youth academy and the rest. <b>Size:</b> everything all Leagues have spent in a city makes it a Town, then a City at 100,000, a Metropolis at 400,000, a Megalopolis at 1.2 million and on (×3 each): bigger cities pay more city income, their visitors spend more, crowds are bigger and tickets dearer, and the top levels of Stadiums, Hotels and Centers need a bigger city. <b>Slots:</b> a city starts with one and gains another at 60,000, 180,000, 400,000 and every doubling after; Stadiums take none. <b>Visitors:</b> every challenger heading for a city\'s gym, or resting at a Pokémon Center there, is a visitor that week. Everything you own costs upkeep. Moving a gym to a city with no gym of yours costs a fee and loses what you built in the old city.'],
    ['Upkeep', `Every building level you own costs ${Math.round(UPKEEP * 100)}% of its price a year, paid weekly, so a large estate costs money to hold. Hotels, Berry Farms, Department Stores and Stadiums usually pay their own way; Schools, Tutors, Labs, training halls and Centers don\'t, they buy strength and draw.`],
    ['Ranch', `A League's own pool of Pokémon (the Ranch page). Its Gym Leaders, Elite Four and Champion field their own Pokémon plus Pokémon from the ranch; gym trainers keep their own. Every Pokémon has a grade (1 to 5 stars, from its IVs) and takes the form its line has at the level of the post that fields it, one post at a time. Staff swap one a month for a better one by their steer and Strategy; what they drop goes into the ranch, and a ranch Pokémon they hold leaves with them. Pokémon come in from catching trips (targeted or by area; Scouting sets the odds and grade), the market (a weekly list plus other Leagues' sales) and staff; they go out sold back for a third of their value, released, or sold to another League. Each costs upkeep a week by grade, and the Ranch building at the seat sets how many it holds. When the ranch has nothing of a typed post's own type left, its holder falls back on their three backup types (types outside their own, likelier ones that answer their weaknesses; at most half the team, swapped back for their own type as soon as one is in the ranch; the gym still counts as its type); when nothing fits even then, weak stopgaps stand in. Rival Leagues run their ranches by their aim. Since 0.36.0 the ranch also keeps alphas, Deltas, shinies and Radiants whole, found by luck on trips, charters and the market, by hunts (a trip for a line in a chosen condition, at a multiple of the price and lower odds) and by outbreak trips; each region has its own Delta lines. A condition multiplies a Pokémon's value, and shinies and Radiants on your Elite Four's and Champion's teams earn showcase income and a little prestige. Challengers keep what they drop in storage (up to ${STORE_MAX}); a new Gym Leader, Elite Four member or Champion lets the League take up to ${STORE_PICKS} of it (one more a scouting office level) into the ranch, and asks more pay the richer it is.`],
    ['Regional encounters', `Each region has its own Pokémon (about ${REGION_SIZE} species, counting evolutions): a family belongs to every region of its generations (Pichu: Kanto and Johto; Sylveon brings Eevee's family to Kalos), and regional forms belong to their region as well (Alolan forms to Alola, Galarian to Galar, Paldean to Paldea, Hisuian ones to Sinnoh). Every type has at least five strong lines in every region. Wild finds, the market, area trips and new challengers' teams come from the region. Others arrive through migration (three or four waves a year, about two months each, mostly from a neighbouring region), and a League's ranch can reach them with a shipping lane, a charter or the Safari Zone. Neighbours: ${NEIGHBOURS.map((ns, r) => `${regionName(r)} (${ns.map(regionName).join(', ')})`).join('; ')}. A challenger moving to another region brings at most three Pokémon from outside it. With regional encounters off (Advanced options), every species is found everywhere.`],
    ['Custom regions', `Regions of your own, made in Advanced options (Custom regions) and kept in this browser. A region always has 8 gym cities, 6 towns and 4 League seats, with names, ports and railways, 2 or 3 neighbours, its own legendaries (one shared with another region can then be held once for each region that has it at home) and its own names for posts. Its list of Pokémon can be copied, generated by type, generation and strength, and edited; thin types and an unusual size are flagged but allowed. Its own new Pokémon work as if added to My Pokédex and can be kept in the region; one with a base stat total over ${DEX_LEGEND_BST} can be a legendary encounter, at home in the region. At a new world a region can be added beside the nine, replace a built-in region's Pokémon only (keeping its name, cities and neighbours) or replace a whole region; Pokémon that lived only in a replaced region move to its neighbours. A region can be closed to rival Leagues. Regions are shared as a file or a paste code; a new Pokémon whose name is already taken is left out on import.`],
    ['Shipping lanes, charters and the safari', `A shipping lane is built in a port city where the League has a gym (Vermilion, Cinnabar, Olivine, Cianwood, Slateport, Lilycove, Dewford, Canalave, Sunyshore; Goldenrod's is the railway) and serves one other region: its Pokémon can be caught on the League's targeted trips and turn up at its market all the time. It costs a weekly fee besides upkeep, and a fee to change the route. A charter is a one-off shipment of two or three Pokémon from any other region. The Safari Zone (one per League, in a gym city) holds foreign Pokémon from mixed regions, changing every 12 weeks, that only the League's own targeted trips can catch; higher levels hold more and bring back better grades, and make safari trips cheaper and likelier. The League keeps 1 to 3 lines it chooses (by level) through each change, and can stock it with up to 4, 8 or 12 of its own ranch Pokémon: they leave the ranch at the same upkeep, their lines stay in the safari, trips for them are likelier and no worse than a grade below the best stocked one, and once a quarter a young Pokémon of a stocked line turns up and joins the ranch. All lapse while the League is in the red (the stock waits; if the safari goes, it comes back to the ranch). The Ranch page's Trips & log tab keeps a log of what every trip, buy and sale did. When a post's steer wants a Pokémon the League can't reach, the Ranch page says where it lives.`],
    ['Youth academy', `A League-level purchase at the seat that takes no slot. Each of its three levels raises a young prospect a year who sets out on your circuit as one of your own: ${Math.round(ACADEMY_LOYAL * 100)}% likelier to take your offers and paid ${Math.round((1 - ACADEMY_PAY) * 100)}% less by you. Rival Leagues build academies too.`],
    ['Banlist', 'In your League the banlist is a paid rule set on the Meta page: any Pokémon seen on your circuit, in any week, for one to three years, priced by its meta rank. Up to three at once; a ban that runs out protects that Pokémon for two years. Other Leagues\' trainers still vote on bans at New Year.'],
    ['Steers', 'A standing instruction for how a post\'s team is built: Balanced, Counter the trend, Counter the year\'s meta, Favour bulk, Hit hard, Cover weaknesses or Keep their own Pokémon. Set on Your staff for each Gym Leader\'s gym (its gym trainers follow it), each Elite Four seat and the Champion, plus a League line for posts with none. It belongs to the post, so a new holder follows it. Everyone follows a steer, as closely as their Strategy allows; it trades some raw strength for what it asks. A team moves one Pokémon closer each month, and someone new to a post builds to it at once. A countering trainer may field one Pokémon off their type. Rival Leagues steer themselves: posts that can answer the meta on their type counter it.'],
    ['The meta', 'The circuit\'s top performers, read at the start of every month: the trend (the last 12 weeks) and the year (last year plus this year so far). Only challengers\' Pokémon count. The Meta page shows both, the types that answer them and which of your posts can answer them on their own type. The sim stops when the trend shifts. Newcomers still lean toward types that counter the year\'s top performers.'],
    ['Seat challenges', 'At New Year a League holds at most one challenge for an Elite Four seat, and a rival League\'s manager may call one for its Champion\'s seat (an Elite Four member who wants promotion, has held the seat a year and didn\'t have the worst record of the four). In your League the Champion\'s seat is challenged only when you call a challenge (see Calling a challenge) or allow a title claim. A Gym Leader who wants promotion and whose gym was one of the three best-holding of the year, or a challenger who reached the Elite Four this year when the seat\'s holder is 50 or older, can challenge the weakest Elite Four seat. It is one battle at the seat\'s level, the challenger with a team built for the seat. A beaten Champion takes the winner\'s Elite Four seat; a beaten Elite Four member takes the winning Gym Leader\'s gym, or returns to the circuit if a challenger beat them. In your League you approve or refuse each challenge within four weeks (unanswered, it goes ahead). A member of staff whose challenge is refused or lost turns restless, and anyone who challenged waits two years to try again. Rival Leagues hold their challenges at once. A new Champion can\'t be challenged for the seat by a claim or another League in their first calendar year.'],
    ['Seat rules', 'Each League has a rule for how its Champion is chosen, set on Your staff (and at setup, free). Protected: the seat changes only with your say (called challenges, title claims, the Champion\'s own ambitions). Succession: when the Champion leaves, the top Elite Four seat moves up. Term: the Champion serves a set term, then you appoint the next one (or keep them); unanswered, they serve another. Council vote: on a schedule and whenever the seat empties, the Elite Four vote; you can lobby for a candidate, and the vote keeps ambitious members patient a little longer. Merit: on a schedule, the seat goes to whoever stopped the largest share of runs (the Champion\'s counts more). Gauntlet (the Grand Trial in island-trial Leagues): each New Year the strongest willing candidate may try to beat every Elite Four member in a row, then the Champion. Champion\'s Cup: on a schedule, the Champion, the Elite Four and the best Gym Leaders play a tournament, and the winner takes the seat; it sells tickets. Open Cup: the Cup with title winners and the circuit\'s best invited, a bigger gate and a little prestige. Conqueror: a title winner takes the seat, as in the main games; you pick the timing. Instant: whoever beats the Champion takes the seat on the spot, with no grace for a new Champion (the beaten Champion drops into an empty Elite Four seat if one is waiting for you, else leaves with a grudge). At New Year: the year\'s strongest title winner who wants the seat takes it. You set how often each scheduled rule comes round. Called challenges and title claims are only for the Protected rule. Changing the rule costs prestige and can\'t be done again for two years. The less control a rule keeps, the more prestige a year it earns, the more challengers it draws and the readier ambitious trainers are to sign. Rival Leagues pick by their theme and aim, and may change rule when they rebrand. A founding Champion\'s window protects the seat from every rule.'],
    ['Calling a challenge', 'You decide when your Champion\'s seat is fought for. Up to three times a calendar year, on Your staff, call a challenge and name the challenger: one of your Elite Four members or Gym Leaders, or a title winner of this year or last still on your circuit (not anyone who challenged in the last two years). It is one battle at the Champion\'s level, four weeks later; you can fight it sooner or call it off. If the challenger wins they take the seat: a beaten Champion takes the winner\'s Elite Four seat or gym, or, beaten by a title winner, leaves the post. A Champion called against is put out by it, more so with each call in a year, and may come to want a bigger League\'s seat or to step down. Rival Leagues call theirs by their aim.'],
    ['Champion ambitions', 'The Champion has an ambition like the rest of the staff: most stay put, but one may want a bigger League\'s seat (with another League in the world; three years, then twelve weeks\' notice, and a raise holds them a year), another run as a challenger, or to step down after a run in the seat (three years, then notice: they retire at 40 or older, else take an Elite Four seat). When a Champion leaves, the strongest Elite Four member moves up at once and their seat waits for you. A League\'s founding Champion stays put through their window.'],
    ['Title claims', 'Beating the Champion wins the title, not the seat. At New Year the strongest of the year\'s title winners who wants a seat (about half of them) can claim the Champion\'s seat. In your League nothing changes without you: allow the claim battle (one battle at the Champion\'s level, your Champion with their full team and a little more than the seat\'s usual edge; a Champion who loses leaves the post, for another League\'s circuit or retirement), turn it down, or offer the claimant a post through the hiring pages, which they are glad to take. Turned down, or unanswered for eight weeks, the claim costs your League 2 prestige and the claimant leaves unhappy, often for another League that may sign them as a contender against you. Rival Leagues allow or turn down claims by their aim. The multi-year sim turns every claim down.'],
    ['Refusing a move', 'Staff take any move up. They refuse a step down (Elite Four to a gym, a gym to a gym trainer\'s place) unless their record is poor, and anyone who wants to stay put or wants another run refuses a sideways move or a swap. Letting someone go always works. Retirees and outsiders always accept.'],
    ['Your staff', 'On the Your staff page you can let any Gym Leader, Elite Four member or gym trainer go, swap two Gym Leaders or two Elite Four members, and pick gym trainers yourself, at any time. A Gym Leader\'s or Elite Four seat that someone leaves waits for you with an acting holder. Picking someone who already holds a post moves them, and their old post opens next. The Champion changes only by stepping down.'],
    ['Hiring', `Anyone you can hire right now: challengers on your circuit, your own staff, trainers who retired in the last ${RETIREE_YEARS} years (under ${RETIREE_MAX_AGE} and still OVR ${RETIREE_MIN_OVR}+), and outsiders the game finds for the post. A challenger gets an offer and can turn it down; then they aren't asked again for half a year. One out on a run who accepts finishes the run first, for up to ${HIRE_NOTICE} weeks, and the post's holder stays until they arrive. Everyone else takes the post at once. Outsiders nobody picks set out as challengers. Rival Leagues hire from their own circuits, recent retirees and outsiders.`],
    ['Impressed', `A challenger on your circuit who reached the Elite Four, or won ${IMPRESS_BADGES} or more badges in a run, this year or last. Worth an offer, though a challenger doing well wants the title and is much likelier to turn a post down.`],
    ['Poor years', `A Gym Leader's year is poor when the gym held under 30% of 12 or more tries; an Elite Four member's warning counts the years in a row they stopped the smallest share of the runs that reached them. Rival Leagues replace a Gym Leader after ${POOR_YEARS} poor years in a row, and an Elite Four member after ${POOR_YEARS} years with the worst record if someone clearly better is free. In your League you only see the warning.`],
    ['Year report', 'Opens at New Year from the Records menu, for the year just ended, and any earlier year can be opened from it or from the year\'s number in the History page\'s wall report. It leads with the trainers let through, then perfect years and the streak, how far the best challenger got and the badges conceded, each against last year, your best year (fewest let through, then fewest badges) and your average. Below: each gym (its leader at year\'s end and anyone else who led it, its gym trainers, tries turned back by the gym trainers and by the leader, badges conceded), each Elite Four seat and the Champion\'s, the year\'s ten furthest challengers and every run at the Elite Four.'],
    ['Badges conceded lately', 'Each of your gyms keeps its last three badges conceded: the battles its leader lost. Watch them from the gym\'s card on the Gyms page.'],
    ['Acting', 'When a Gym Leader or Elite Four member leaves your League, the post waits for you. Meanwhile the gym\'s stronger gym trainer stands in as acting leader (the gym runs one gym trainer short), or a stand-in holds the Elite Four seat. The Champion\'s seat is never empty: the strongest Elite Four member moves up.'],
    ['Tries', `A challenger gets ${GYM_TRIES} tries at each gym on a run. A loss to a gym trainer or the leader costs one. A third loss at the same gym ends the run: they rest, then start again with no badges. After a loss they may go to another gym and come back later: tries used stay used and gym trainers beaten stay beaten, but by then they hold more badges, so the gym fields more Pokémon at a higher level.`],
    ['Gyms in any order', `Challengers take the gyms in any order. Every gym scales to the challenger in front of it: it fights at the level and team size for the badges they already hold, so a gym sees beginners and challengers close to the Elite Four alike. A Gym Leader holds up to ${LEADER_HOLD} Pokémon and a gym trainer up to ${GT_HOLD}; each fields what the battle needs, picked by their Strategy against the challenger. A challenger picks their next gym after every badge and every loss: the one their team matches best, putting off gyms that beat them before (gym memory) and gyms where they have used tries. A sharp trainer reads it well; a poor one picks close to randomly. Gym numbers are a pecking order: later gyms pay more and are a step up for a Gym Leader who wants promotion. The year report shows each gym's share of tries held by stage (early 0–2 badges, mid 3–5, late 6–7), and the progress board counts challengers by badges held.`],
    ['Perfect year', 'A calendar year in which no challenger beats your Champion. The streak counts perfect years in a row, and the header shows how long it has been since a title was last conceded. The wall report on the History page has every year, with badges conceded and how far the best challenger got.'],
    ['Elite Four', 'Four battles in a row at the League, then the Champion. One loss ends the run.'],
    ['Champion', 'A challenger who beats the Champion wins a title, and the League has conceded one. The Champion keeps the seat and only leaves by retiring; for now the strongest Elite Four member then moves up.'],
    ['World Championship', 'With several Leagues, their Champions meet after the season.'],
    ['Triple Crown', 'Champion of three different Leagues across a career. A trainer with titles in 2+ Leagues gets 3 extra years before age can retire them.'],
    ['Progress board', 'A page of its own (Board in the header) showing how far everyone has got against a League: one row per gym, Elite Four seat and the Champion, with the challengers there now, how many it let through and walled this year, and the share of tries it held. Open a row for who is there and on which try, who got through lately with the core of their team, who was walled and by whom, and the types beating it. The threats strip lists challengers with six badges or more, contenders and anyone who impressed. The League switcher shows any League\'s board.'],
    ['Gym memory', `A challenger who loses at a gym remembers the types of the trainer who beat them there. On later tries they pick their squad against those types, and between tries they lean their catches toward counters (and sometimes go looking for one). Strategy sets how well they learn. The memory is kept across runs at that League, never carried to another, and wiped when the gym changes: a new leader or gym trainer, or about ${Math.round(GMEM_CHANGE * 100)}% of its line's Pokémon replaced since (steers, a leader adapting, bans). A gym that never changes wears down; one that keeps changing holds.`],
    ['Hall of Fame', 'Every title win, entered the moment the Champion is beaten, with the team that won it, the year, the League, the Champion beaten and a contender tag. A trainer who wins again gets another entry. Anyone with an entry is a Hall of Famer, and each entry adds to their prestige.'],
    ['Hall of Shame', "Records nobody wants: worst win rates, longest losing streaks and the like."],
    ['Meta', 'The five best-performing species of the season. Newcomers lean toward types that counter them.'],
    ['Rival', 'Two challengers who keep meeting in close road battles.'],
    ['Nemesis', 'Someone a trainer has lost to five times or more without a win.'],
    ['Crossroads', 'After 10 years without finishing the circuit, a trainer may retire or reinvent themselves with a new class.'],
    ['Legacy trainer', 'The child of a decorated retiree, setting out as a challenger with their parent\'s type.'],
    ['Famous trainer', 'Characters from the games, anime and optional packs, who keep their own type and signature Pokémon.'],
    ['Season awards', Object.values(AWARDS).map(a => a.name).join(', ') + '.'],
  ],
};
// (0.64.0) city buildings part 2
GLOSS_TERMS.league.push(['Stadium add-ons', `A Stadium's levels add seats (ticket income) and open its add-ons, which take no slot and work for your staff in that Stadium's battles (at the seat: the Elite Four, the Champion and title claims) while the Stadium is at least the level they open at, and not while you are in the red. Home stand (Stadium level 1): a home edge of up to +${(STAND_EDGE * 100).toFixed(1)}% a level at a full house, less with empty seats. Field crew (level 2): Pokémon of the gym's type (every Pokémon at an untyped gym; at the seat, the battling trainer's type) hit ${Math.round(CREW_HIT * 100)}% harder a level. Video room (level 3): +${VIDEO_STR} Strategy a level when your staff choose which Pokémon to field against a challenger and when to send them out. Warm-up room (level 4): the first Pokémon of the team goes out a stage up in its better attacking stat, the first two at level 2, the first three at level 3. 3 levels each.`]); // (0.68.0)
GLOSS_TERMS.league.push(['Weather Institute', `One per League, in a gym city that is at least a City, built from the Cities page; it works League-wide. It sets the field for each of your gyms' battles and for the seat's (the Elite Four, the Champion and title claims): one weather (rain, sun, sand, snow), one terrain (Electric, Grassy, Psychic, Misty) or clear skies, never a weather and a terrain together. The field replaces the gym's own weather (a gym left unset keeps the weather of its leader's type). A terrain powers its type's moves 20% for both sides. At level 1 a place can only use the fields its types bring (a Water gym rain, an Electric gym Electric Terrain); a weather-themed trainer on your staff opens them all. At level 2 any field works anywhere, and it holds all battle: no ability or move changes the weather. Challengers can see every field, and the sharper ones (Strategy) pick their Pokémon and their next gym with it in mind. It stops working in the red.`]); // (0.69.0)
GLOSS_TERMS.league.push(['Airport', `A gym-city building, one a League, in a City or bigger (3 levels: a second route needs a Metropolis, level 3 a Megalopolis). Each route to another region works like a shipping lane (its Pokémon on your targeted trips and at your market) and brings people: challengers moving out of that region lean toward your League and land in the Airport's city (a few weeks as visitors there), and about ${AIR_VISITS} visitors a month arrive from there (up to twice as many with your renown in its cities). Visitors spend in the city like any other (Hotels, where level 3 counts them twice, Department Stores). It costs ${money(AIR_WEEK)} a week to run and earns ${money(AIR_LAND)} for every arrival; changing a route costs ${money(AIR_ROUTE)}. Level 3 makes charters ${Math.round(AIR_CHARTER * 100)}% cheaper and a week faster, and your contenders win 25% more renown in other regions. In the red it lapses: no routes, no arrivals, no fee.`],
  ['Game Corner', `A gym-city building (3 levels) that needs a City (level 3 a Metropolis). The city's visitors and residents play there each week, up to ${CORNER_SEATS.join(', ')} seats by level (every Game Corner in a city shares them; the controlling League's a little more), each spending by the city's size. The take swings: most weeks within 30% of its average, about 1 week in ${CORNER_JACK_N} a jackpot of about ${CORNER_JACKPOT} times as much, and about 1 week in ${CORNER_LOSS_N} a losing week, when the house pays out more than it takes. Its prize counter holds ${CORNER_PRIZES.join(', ')} of your region's rarest Pokémon by level (never a legendary or Paradox Pokémon), grade ${CORNER_MIN_G} or better, at ${Math.round(CORNER_MARKUP * 100)}% of their market value (10% off at level 3); it changes every quarter, each prize can be taken once, and it goes straight into your ranch. Closed in the red. Money-making rival Leagues build one in their busiest City; the others take prizes that fit their staff's types.`],
  ['Bug Catching Contest', `A gym-city building (3 levels; 3 needs a City) where the gym is a Bug gym, or with a Bug Catcher or Bug Maniac on your staff. Every ${CONTEST_WEEKS} weeks it brings your ranch 1, 2 or 3 of your region's Bug Pokémon (migrants in season too), the first, the prize, at grade ${CONTEST_PRIZE.join(', ')} or better by level, at a little better than the wild odds for a condition, plus ${CONTEST_VISIT} visitors a level and a gate of ${money(CONTEST_GATE)} a level. If the condition is lost it keeps running but can't be raised.`],
  ['Fishing Pier', `A gym-city building (3 levels: the rods; the Super Rod needs a City) in a port, where the gym is a Water gym, or with a Fisherman on your staff. One Water Pokémon of your region every ${PIER_WEEKS} weeks: the Old Rod the weakest third of the region's Water lines by their final form's strength, the Good Rod the middle third too, the Super Rod all of them. If the condition is lost it keeps running but can't be raised.`],
  ['Fossil Lab', `A gym-city building (3 levels; 3 needs a City) where your Research Lab is at level 2 or more. It revives a fossil Pokémon from any region (your region's own ${FOSSIL_HOME} times as often) every ${FOSSIL_WEEKS.slice(0, 3).join(', ')} weeks by level, at a grade no lower than its level; a Ruin Maniac on your staff counts as one more level (every ${FOSSIL_WEEKS[3]} weeks at the most). If the condition is lost it keeps running but can't be raised.`],
  ['Keep grade', 'The grade (1 to 5) a find from a Bug Catching Contest, Fishing Pier or Fossil Lab must reach to join your ranch. Each building uses your League\'s grade floor (Ranch rules) unless the Cities page gives it its own; finds below it are sold back at once for a third of their value, and a find for a full ranch makes room if your rules allow, else it is sold back.'],
  ['Ranch rules', 'Set on the Ranch page\'s Pool tab, each on or off. Grade floor: anything that comes in on its own (trips, hunts, charters, outbreak trips, Safari finds, the Day Care\'s young, the catching buildings) below the floor is sold back at once. Make room: a find for a full ranch replaces your weakest spare (by value) if it is worth more. Idle clear-out: spares nobody has fielded for a number of weeks are sold, keeping your best few of each line. List first: idle clear-outs, and your weakest spares when the ranch is nearly full, are listed for other Leagues for 4 weeks before selling back. A spare is a ranch Pokémon nobody fields, reserves, locks or plans for; alphas, Deltas, shinies and Radiants only with Conditioned too. A new League starts with the floor at two stars and make room on. Rival Leagues keep a floor and make room by their aim.']);
GLOSS_TERMS.league.push(['Trainer\'s School', `A gym-city building (4 levels; 3 needs a City, 4 a Metropolis). Each level graduates one young trainer a year (16 to 20, from that city, of a class that fits the gym), a little stronger each level than the field's typical gym trainer; a Pokémon Professor anywhere on your staff counts as one more level. A graduate takes an open gym trainer place at that gym, else at another of your gyms they fit; otherwise they set out on the region's field from that city, ${Math.round(ACADEMY_LOYAL * 100)}% likelier to take your offers, and your gym trainer picker lists them first. Rival Leagues also let a weaker gym trainer go at the end of a contract to take one on. Your graduates are paid ${SCHOOL_PAY.map(x => Math.round((1 - x) * 100) + '%').join(', ')} less by you, by the School's level when they graduated. The School is also that gym's training hall: its Gym Leader and gym trainers grow 12% faster a level and decline more slowly. The training hall itself is at the seat only now (the Elite Four and Champion). In the red a School lapses: no graduates, no growth bonus.`],
  ['Move Tutor', `A building in a gym city (its Gym Leader and gym trainers) or at the seat (the Elite Four and Champion), 3 levels. A tutored Pokémon learns all three of its line's coverage types instead of two, each ${TUTOR_SOONER} levels sooner, in an order its trainer's Strategy picks (a sharp strategist puts the types that answer the year's meta first). The lesson stays with the Pokémon for good, in the ranch and on whoever fields it next. Level 1 teaches ${TUTOR_FEW} Pokémon a post (planned ones first, then the strongest), level 2 the whole team; level 3 (needs a City) makes a backup-type Pokémon's coverage hit its trainer's own threats first. Lessons are given once a month; in the red, none, but lessons already taught stay.`],
  ['Research Lab', `A gym-city building (4 levels; 3 needs a City, 4 a Metropolis). Catching trips aren't tied to a city, so your best Lab works League-wide, and a Scientist on your staff counts as one more level: +${LAB_SCOUT} Scouting a level for catching trips; finds of grade 2 or better from level 2 and grade 3 or better from level 4; one more trip out at a time from level 3; condition hunts ${Math.round(LAB_HUNT * 100)}% likelier a level; at level 4 ordinary trips find conditions 1.5× as often. A research grant of ${LAB_GRANT} × its level for every new species of your region your ranch takes in (until the regional Pokédex comes, the ranch's own register).`],
  ['Department Store and the item bag', `Staff hold tier 1 items from the League's free supply as before. Tier 2 and 3 items (Leftovers, Eviolite, Assault Vest, Expert Belt, Focus Sash, Life Orb, Choice Band, Choice Specs) come only from your League's item bag: your Gym Leaders, Elite Four and Champion take the best of it, one item a Pokémon, and an item comes back when its Pokémon leaves the team or its holder the League. A challenger you hire to one of those posts brings their tier 2 and 3 items into the bag. Department Stores (gym cities, 4 floors) sell them, League-wide by your best Store's floors: the Poké Mart floor tier 1 items, 2F Leftovers, Eviolite and Assault Vest, 3F Expert Belt and Focus Sash (a City), 4F Life Orb and the Choice items (a Metropolis); each floor above a shelf takes ${Math.round(STORE_FLOOR_OFF * 100)}% off it. Items are bought once, with no upkeep. A Store also earns from shoppers: the city's visitors plus its residents (more in a bigger city), ${STORE_SHOPPERS} a floor, shared between the city's Stores by floors with a little more to the League that controls it. Rival Leagues buy by aim: wall-builders the strongest items, money-makers only the cheaper shelves. The item bag is on the Cities page.`]);

const GLOSS_SECS = [['all', 'All'], ['abilities', 'Abilities'], ['moves', 'Moves'], ['items', 'Items'], ['traits', 'Trainer traits'], ['tempers', 'Temperaments'], ['ratings', 'Ratings'], ['plans', 'What trainers do'], ['battle', 'Battle terms'], ['mons', 'Pokémon terms'], ['league', 'League & careers']];
let glossCache = null;
function glossEntries() {
  if (glossCache) return glossCache;
  const out = { abilities: [], moves: [], items: [], traits: [], ratings: [], tempers: [] };
  const holders = {}; for (const [sp, A] of Object.entries(SPECIES_AB)) for (const k of ['0', '1', 'H']) if (A[k]) (holders[A[k]] = holders[A[k]] || []).push(sp);
  for (const [a, d] of Object.entries(ABILITIES).sort((x, y) => x[0].localeCompare(y[0]))) { const h = (holders[a] || []).filter(sp => SP[sp] && !SP[sp].legend); const eg = (h.length ? h : holders[a] || []).slice(0, 4); out.abilities.push({ n: a, d, x: eg.length ? 'e.g. ' + eg.join(', ') : '' }); }
  for (const mv of Object.values(MOVES).sort((x, y) => x.name.localeCompare(y.name))) out.moves.push({ n: mv.name, d: moveLine(mv, null), chip: chip(mv.type), x: [mv.sig && SIG_MOVES[mv.name] ? 'Signature of ' + SIG_MOVES[mv.name].join(', ') : '', mv.tier >= 3 ? 'learned from Lv 40' : mv.tier === 2 ? 'learned from Lv 22' : ''].filter(Boolean).join(' · ') });
  for (const [k, it] of Object.entries(ITEMS).sort((x, y) => x[1].name.localeCompare(y[1].name))) out.items.push({ n: it.name, d: it.desc, x: it.tier === 3 ? 'Rare' : it.tier === 2 ? 'Uncommon' : 'Common' });
  for (const t of Object.values(TRAITS)) out.traits.push({ n: t.name, d: t.text });
  for (const [n, x] of Object.entries(TEMPER)) out.tempers.push({ n: `${n} · ${x.name}`, d: x.d, x: natureText(n) });
  for (const k of RK) out.ratings.push({ n: RNAME[k], d: RATING_TEXT[k] });
  for (const [sec, list] of Object.entries(GLOSS_TERMS)) out[sec] = list.map(([n, d]) => ({ n, d }));
  return glossCache = out;
}
function glossResults() {
  const all = glossEntries(), q = fold(glossQ.trim());
  const secs = GLOSS_SECS.filter(([k]) => k !== 'all' && (glossSec === 'all' || glossSec === k));
  let total = 0;
  const html = secs.map(([k, label]) => {
    const rows = all[k].filter(e => !q || fold(e.n + ' ' + e.d.replace(/<[^>]+>/g, '') + ' ' + (e.x || '')).includes(q));
    total += rows.length; if (!rows.length) return '';
    const shown = glossSec === 'all' && !q ? rows.slice(0, 6) : rows;
    return `<section class="gl-sec"><div class="gl-h"><h3>${label}</h3><span class="muted small">${rows.length}</span></div>
      <dl class="gl">${shown.map(e => `<div class="gl-row"><dt>${esc(e.n)}${e.chip ? ' ' + e.chip : ''}</dt><dd>${e.d}${e.x ? ` <span class="muted small">· ${esc(e.x)}</span>` : ''}</dd></div>`).join('')}</dl>
      ${shown.length < rows.length ? `<button class="link" data-act="glosssec" data-v="${k}">All ${rows.length} ${label.toLowerCase()} ›</button>` : ''}</section>`;
  }).join('');
  return total ? html : `<p class="muted">Nothing matches “${esc(glossQ.trim())}”.</p>`;
}
function glossaryBody() {
  return `<div class="mh"><h2>Glossary</h2><button class="btn icon" data-act="close" aria-label="Close">×</button></div>
  ${searchBox('glosssearch', glossQ, 'Search the glossary', 'Search abilities, moves, items, terms…')}
  <div class="filters">${GLOSS_SECS.map(([k, l]) => `<button class="pill${glossSec === k ? ' on' : ''}" data-act="glosssec" data-v="${k}">${l}</button>`).join('')}</div>
  <div id="glossres">${glossResults()}</div>`;
}

// ---------- updates ----------
// newest first; add an entry with every published change.
// Versioning rule (from v179 on): every new version gets the next id, a date AND a timestamp (Eastern Time),
// and all changes made in one working session go into that one version's entry.

// ---------- god mode ----------
let godLg = 0, godPick = null, godRole = 'challenger';
const GOD_RATINGS = { str: 'Strategy', trn: 'Training', bnd: 'Bonding', sct: 'Scouting', nrv: 'Nerve' };
const GOD_ROLES = { challenger: 'Challengers', leader: 'Gym Leaders', e4: 'Elite Four and Champion' };
function godEditor() {
  if (godLg >= nLeagues()) godLg = 0;
  const list = Object.values(S.trainers).filter(x => lgOf(x) === godLg && (godRole === 'e4' ? ['e4', 'champion'].includes(x.role) : x.role === godRole)).sort((a, b) => ovr(b) - ovr(a));
  const t = godPick != null && T(godPick) && list.some(x => x.id === godPick) ? T(godPick) : null;
  const row = x => `<div class="pt-row${t === x ? ' sel' : ''}"><div class="pt-id">${tname(x.id)} ${ovrPill(x)} <span class="muted small">age ${x.age} · POT ${x.pot} · ${roleHere(x)}</span></div><div class="pt-act"><button class="btn small${t === x ? ' primary' : ''}" data-act="godpick" data-id="${x.id}">${t === x ? 'Close' : 'Edit'}</button></div></div>`;
  const num = (id, label, v, lo, hi) => `<label class="cf-field"><span class="eyebrow">${label}</span><input id="${id}" class="cf-in" type="number" inputmode="numeric" min="${lo}" max="${hi}" value="${v}"></label>`;
  const form = t ? `<div class="pt-life"><div class="ph"><h3>${dn(t)}</h3><span class="muted">OVR ${ovr(t)}</span></div>
      <div class="cf-grid six"><label class="cf-field"><span class="eyebrow">Name</span><input id="ge-name" class="cf-in" maxlength="24" value="${esc(t.name)}" autocomplete="off"></label>
        ${num('ge-age', 'Age', t.age, 10, 70)}${num('ge-pot', 'Potential', t.pot, 1, 99)}</div>
      <div class="eyebrow">Ratings</div><div class="cf-grid six">${RK.map(r => num('ge-' + r, GOD_RATINGS[r], t.r[r], 1, 99)).join('')}</div>
      <div class="confirm-row"><button class="btn primary" data-act="godsave" data-id="${t.id}">Save changes</button></div></div>` : '';
  return `<section class="panel"><div class="ph"><h3>Trainers</h3><span class="muted">${list.length} shown</span></div>
    <div class="release">${Object.keys(GOD_ROLES).map(k => `<button class="rel${godRole === k ? ' on' : ''}" data-act="godrolesel" data-k="${k}">${GOD_ROLES[k]}</button>`).join('')}</div>
    ${nLeagues() > 1 ? `<div class="release" style="margin-top:6px">${Array.from({ length: nLeagues() }, (_, i) => `<button class="rel${godLg === i ? ' on' : ''}" data-act="godlgsel" data-i="${i}">${lgShort(i)}</button>`).join('')}</div>` : ''}
    ${form}${list.map(row).join('') || '<p class="muted">Nobody here.</p>'}</section>`;
}
function viewGod() {
  if (!godOn()) return viewCircuit();
  return `<section class="panel callout"><div class="eyebrow">God mode</div><h2>Shape the world by hand</h2>
    <p>Open a League, or edit any trainer directly. These skip the usual limits.</p></section>
  <section class="panel"><div class="ph"><h3>Leagues</h3><span class="muted">${nLeagues()} Leagues open</span></div>
    <p>${Array.from({ length: nLeagues() }, (_, i) => leagueName(i)).join(' · ')}</p>
    <div class="confirm-row"><button class="btn primary" data-act="godleague" ${nextRegion() != null ? '' : 'disabled'}>${nextRegion() != null ? `Open the ${nextRegionName()} now` : 'The world is full'}</button></div></section>${godEditor()}`;
}

// ---------- post holders (0.49.0) ----------
// Every post of the League on view, year by year: who held it at each New Year (a mark where it changed hands, and
// anyone else who held it during the year), or post by post as tenures. Read from each year's history entry
// (`gyms[i].leader`/`lead`, `seats[k].id`/`held`, k 4 = the Champion), with this year's holders as the top row.
let postsMode = 'year';
function postCols() {
  return [{ k: 's4', label: postWord('champion'), now: () => S.champion }]
    .concat([0, 1, 2, 3].map(k => ({ k: 's' + k, label: `${postWord('e4')} #${k + 1}`, now: () => S.e4[k] })))
    .concat(S.gyms.map((g, i) => ({ k: 'g' + i, label: `${townName(i)} ${postWord('leader')}`, short: townName(i), now: () => g.leader })));
}
// a year's holder of a post: { id, acting, also: [others who held it during the year] }
function postAt(h, k) {
  const x = k[0] === 's' ? (h.seats || [])[+k.slice(1)] : (h.gyms || [])[+k.slice(1)];
  if (!x) return null;
  const id = k[0] === 's' ? x.id : x.leader, during = (k[0] === 's' ? x.held : x.lead) || [];
  return { id, acting: !!x.acting, also: during.filter(o => o != null && o !== id) };
}
function postNow(c) { const id = c.now(), t = T(id); return { id, acting: !!(t && t.acting), also: [] }; }
const pName = id => { const t = T(id); return t ? `<button class="tlink" data-act="profile" data-id="${id}">${esc(t.name)}${t.famous ? '<span class="star">★</span>' : ''}</button>` : '<span class="muted">—</span>'; };
function postCell(p, prev) {
  if (!p || p.id == null) return '<td class="muted">—</td>';
  const chg = prev && prev.id !== p.id;
  const also = p.also.length ? ` <span class="small muted" title="Also held it this year: ${esc(p.also.map(o => (T(o) || {}).name || '?').join(', '))}">+${p.also.length}</span>` : '';
  return `<td class="${chg ? 'phchg' : ''}">${pName(p.id)}${p.acting ? ' <span class="tag">acting</span>' : ''}${also}</td>`;
}
function postTenures(cols, rows) {
  // rows oldest first: [{ season, get(k) }]; a tenure is a run of years with the same year-end holder
  return cols.map(c => {
    const ten = [];
    for (const r of rows) { const p = r.get(c.k); if (!p || p.id == null) continue;
      const last = ten[ten.length - 1];
      if (last && last.id === p.id && last.to === r.season - 1) last.to = r.season; else ten.push({ id: p.id, from: r.season, to: r.season, now: false });
      if (r.now) ten[ten.length - 1].now = true; }
    return { c, ten: ten.reverse() };
  });
}
function viewPosts() {
  const cols = postCols(), hist = S.history.filter(h => h.gyms || h.seats);
  const nowRow = { season: S.season + 1, now: true, get: k => postNow(cols.find(c => c.k === k)) };
  const rows = hist.map(h => ({ season: h.season, get: k => postAt(h, k) })).concat([nowRow]);
  const seg = (v, l) => `<button class="seg${postsMode === v ? ' on' : ''}" data-act="postsmode" data-v="${v}" aria-pressed="${postsMode === v}">${l}</button>`;
  const head = `<div class="ph"><h2>Post holders${nLeagues() > 1 ? ' · ' + S.lgName : ''}</h2><span class="muted">${hist.length} year${hist.length === 1 ? '' : 's'} recorded</span></div>
    <div class="segs" style="margin-bottom:8px">${seg('year', 'By year')}${seg('post', 'By post')}</div>`;
  let body;
  if (postsMode === 'post') {
    body = postTenures(cols, rows).map(({ c, ten }) => `<div class="phpost"><h3>${esc(c.label)}</h3>${ten.length ? `<table class="tbl"><tbody>${ten.map(x => {
      const n = x.to - x.from + 1, yrs = x.now ? (x.from === S.season + 1 ? 'this year' : `Year ${x.from} – now`) : x.from === x.to ? `Year ${x.from}` : `Years ${x.from}–${x.to}`;
      return `<tr${x.now ? ' class="sel"' : ''}><td>${pName(x.id)}</td><td class="small">${yrs}</td><td class="num small muted">${n} year${n === 1 ? '' : 's'}${x.now ? ' so far' : ''}</td></tr>`; }).join('')}</tbody></table>` : '<p class="muted">Nobody yet.</p>'}</div>`).join('');
    body = `<div class="phgrid">${body}</div>`;
  } else {
    const desc = rows.slice().reverse();
    body = `<div class="scroll"><table class="tbl phtbl"><thead><tr><th>Year</th>${cols.map(c => `<th title="${esc(c.label)}">${esc(c.short || c.label)}</th>`).join('')}</tr></thead><tbody>
      ${desc.map((r, i) => { const prev = desc[i + 1]; return `<tr${r.now ? ' class="sel"' : ''}><td class="num">${r.now ? 'Now' : r.season}</td>${cols.map(c => postCell(r.get(c.k), prev && prev.get(c.k))).join('')}</tr>`; }).join('')}
    </tbody></table></div>`;
  }
  return `<section class="panel">${head}${body}
    <p class="fine">${postsMode === 'year' ? `Who held each post at the end of each year; the top row is now. A gold edge marks a post that changed hands that year, +N anyone else who held it during the year (hover for names). Gym columns are named by where each gym is now.` : 'Each post\'s holders at the end of each year, newest first; the highlighted row holds it now.'} Use the League buttons above to see another League.</p></section>`;
}
